class BankAccount:
    def __init__(self, account_number, owner, balance=0.0):
        self.account_number = account_number
        self.owner = owner
        self.balance = balance
        self.transaction_history = []

    def deposit(self, amount):
        if amount > 0:
            self.balance += amount
            self.transaction_history.append(f"Deposited {amount}")
        else:
            raise ValueError("Deposit amount must be positive")

    def withdraw(self, amount):
        if amount > self.balance:
            raise ValueError("Insufficient funds")
        self.balance -= amount
        self.transaction_history.append(f"Withdrew {amount}")

class Bank:
    def __init__(self):
        self.accounts = {}

    def create_account(self, acc_num, owner, initial_balance=0.0):
        if acc_num in self.accounts:
            raise ValueError("Account already exists")
        self.accounts[acc_num] = BankAccount(acc_num, owner, initial_balance)

    def get_account(self, acc_num):
        return self.accounts.get(acc_num)

    def transfer(self, from_acc, to_acc, amount):
        sender = self.get_account(from_acc)
        receiver = self.get_account(to_acc)
        if not sender or not receiver:
            raise ValueError("One or both accounts do not exist")
        sender.withdraw(amount)
        receiver.deposit(amount)

def run_simulation():
    my_bank = Bank()
    my_bank.create_account("A1", "Alice", 500.0)
    my_bank.create_account("B2", "Bob", 200.0)
    my_bank.transfer("A1", "B2", 100.0)

    acc_a = my_bank.get_account("A1")
    print(f"Alice balance: {acc_a.balance}")

    acc_b = my_bank.get_account("B2")
    print(f"Bob balance: {acc_b.balance}")

    print("Transaction history for Alice:")
    for tx in acc_a.transaction_history:
        print(tx)

    print("Transaction history for Bob:")
    for tx in acc_b.transaction_history:
        print(tx)

    print("Testing list index out of bounds...")
    # This will cause an IndexError because the list only has 1 item
    print(acc_a.transaction_history[1])

if __name__ == "__main__":
    run_simulation()
